#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    int weight[55];
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        weight[i] = c - 'a' + 1;
    }

    sort(weight, weight + n);

    int sum = weight[0];
    int last = weight[0];
    int count = 1;

    for (int i = 1; i < n && count < k; ++i) {
        if (weight[i] - last >= 2) {
            sum += weight[i];
            last = weight[i];
            ++count;
        }
    }

    cout << (count == k ? sum : -1) << '\n';
    return 0;
}

