#include <string>
#include <algorithm>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    string s;
    cin >> s;
    sort(s.begin(), s.end());

    int sum = 0, count = 0;
    char last = 0;

    for (char c : s) {
        if (count == 0 || c - last >= 2) {
            sum += c - 'a' + 1;
            last = c;
            if (++count == k) break;
        }
    }

    cout << (count == k ? sum : -1) << '\n';
    return 0;
}

